      '「いま三時五分」という感覚は、当然のものではない。かつて人類の「いま」は、村ごとに、職業ごとに、太陽の角度ごとに違った。時間が世界で同じ幅を持つようになったのは、鉄道と工場が同期を要求したからだ。列車は待ち合わせなければ衝突し、機械は交代しなければ止まる。時計の針は、まず物流と生産の安全のために統一された。規格化されたのは針だけではない。「遅刻」という概念も、共通の時計が生んだ発明である。太陽の下では、遅刻という罪は存在しない。\nこの規格化がもたらしたものは巨大だった。予約ができる。会合が成立する。見知らぬ数百万人が「九時」に同時に動き出す。個人の行動が、見えない他者たちと同じ目盛りに乗る。社会の生産性は、この同期の上に立っている。\nただし、規格には代償がつきものだ。共通の目盛りは、人間の内側の時間の幅を平らにした。集中するひとの一日と、散漫なひとの一日は、同じ長さではない。眠りの深い夜と、浅い夜もだ。⟪時計は誰の時間も正さない。全員の時間を、同じ幅に引き伸ばしたり折りたたんだりして、一つの寸法に押し込むだけである⟫。生産と物流の安全には、この押し込みが要だった。「要だった」と過去形で書くのは、近年、同期を強制しない技術が育ったからだ。記録は残り、連絡は届き、同じ時刻に同じ机につく必然性は、職種ごとに減りつつある。\n同期が解けて、どうなるか。規格が緩む場所から、時間の幅の個人差が戻ってくる。戻ってきた個人の時間は、共通の目盛りと日々せめぎ合う。そのせめぎ合いを「自分の都合」と「社会の都合」の板挟みとしてしか受け取れないなら、規格化はただの不自由だったことになる。目盛りは便利さの発明であると同時に、幅の押し売りでもあった。両方を一度に覚えている社会のほうが、緩め方を誤らない。',
