    passage:
      '年功序列の見直しは、もはや流行ですらない。能力主義の名のもとに、年齢という物差しを撤去する会社が増えた。撤去の議論はおおむね正しい。ただ、年功という制度が単なる惰性ではない理由も、一度検分しておいてよい。\n年功が買っていたものは、二つある。一つは、若い世代の失敗のコストを、組織が引き受けていたことだ。経験の浅い年月は、失敗の量で言えば若い。給与を低く抑える代わりに、失敗を教育費として数えない——この暗黙の交換が、年功には含まれていた。もう一つは、予測可能性である。昇給の道筋が年齢で決まっている人生は、二十代から五十年先まで概算できる。生活設計という観点では、これは馬鹿にできない利点だった。\n能力主義は、この二つの保護を同時に外した。失敗は個人の責任となり、将来の見通しは各自の成績次第となった。個人の努力の機会は広がった。同時に、組織が担っていたリスクは、静かに個人へ転嫁された。年功を撤去する議論をするときは、撤去する物の値段も一緒に読むべきだ。年功の非効率の正体は、リスクを組織側で抱えていたことである。その抱え方を現代に合わせて作り直すのではなく、抱え手ごと廃棄したのが、この四半世紀の流れだった。',
