    passage:
      '人に教えると、自分の理解が深まる——これは感心の話ではなく、仕組みの話として説明できる。理解には深さの段階があって、他人に説明できるレベルは、その頂上近くにある。自分には分かる、という状態には、実は何段階もあって、「読んで分かった」「使って分かった」は、いずれも「人に説明して分かった」より手前の段階だ。説明は、自分の理解の抜けを、聞き手の顔から発見する作業である。「なぜですか」と聞かれた箇所が、理解の未工事の箇所だ。本を読むだけでは、質問は発生しない。\nだから、学んだことを誰かに話す習慣は、学習の最後の一工程として機能する。話す相手は、同程度の素人でよい。むしろ素人のほうが、専門家が気づかない質問をする。説明のために例を探すと、自分の引き出しの薄さも測れる。引き出しが一つしかない知識は、まだ借り物の可能性が高い。自分の言葉で作り直した知識は、例をいくつも持っている。\nもっとも、この効果を逆手に「教える側に回れば学べる」と考えるのは、順序の取り違えだ。教える効果は、学んだ後の点検として働く。何も学んでいない段階で教え役を引き受けると、うろ覚えのまま教えることになり、間違いが固まる。点検は、製造の後に行う。学びの後の教えることだからこそ、効果がある。',
